SourceCode.Declaration:
/// <summary>
/// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
/// custom TAMRebateQueryBuilder to change the source of transaction to METRebateScanSupplierTable where VendAccount is populated
/// </summary>
using System.ComponentModel.Composition;
[ExportAttribute(identifierStr(Dynamics.AX.Application.TAMRebateQueryBuilder))]
[ExportMetadata(enumStr(ModuleInventCustVend), enumLiteralStr(ModuleInventCustVend, Vend))]
[ExportMetadata(enumStr(TAMRebateSourceType), enumLiteralStr(TAMRebateSourceType, METExternalSalesData))]
public final class METTAMRebateQueryBuilderVendExternalData extends METTAMRebateQueryBuilderExternalData
{
}

Method.Source:
public FieldId orderAccountJourTableFieldId()
{
    return fieldNum(METRebateScanSupplierTable, VendAccount);
}

public FieldId invoiceAccountJourTableFieldId()
{
    return fieldNum(METRebateScanSupplierTable, VendAccount);
}

protected FieldId accountMainTableFieldId()
{
    return fieldNum(VendTable, AccountNum);
}

/// <summary>
/// Add extra filters for the external sales data
/// </summary>
protected void addTransRange()
{        
    // Exclude records with a customer account        
    query.dataSourceTable(tableNum(METRebateScanSupplierTable)).addRange(fieldNum(METRebateScanSupplierTable, CustAccount)).value(SysQuery::valueEmptyString());

    // Bug 286663: CB705- Vendor deals are not filtering based on the header vendor account
    this.metAddVendAccountRange();

    super();
}
